function randomItem(arr){
if(isPre()){
if(arr === SHAPES) arr = PRE_SHAPES;
else if(arr === COLORS) arr = PRE_COLORS;
}
return arr[Math.floor(Math.random()*arr.length)];
}
function randomInt(min, max){ return min + Math.floor(Math.random()*(max-min+1)); }

