const B = (pre ? sp.preBoxes : sp.boxes)[t], A = (pre ? sp.preAnimals : sp.animals)[t], R = sp.rounds;
wmState = { kind:"where", B, A, round:0, rounds:R, wrong:0, phase:"idle", boxes:[], ask:[], askIdx:0, res:[] };
