const JAR_PUZZLES = [ [[[2, 5], 3, 2], [[3, 7], 4, 2], [[4, 6], 2, 2], [[3, 5], 2, 2]], [[[3, 5], 1, 4], [[3, 5], 4, 6], [[4, 7], 6, 6]], [[[8, 5, 3], 4, 7], [[10, 7, 3], 5, 6], [[9, 4], 6, 8]] ];
