if(st.phase === "idle"){ info = "▶ Başlat'a bas"; body = dots; }
else if(st.phase === "done"){ info = `Bitti · ${st.scores.map((x, k) => `${k + 1}. tur ${x}/${st.pairs.length}`).join(" → ")}`; body = dots; }
