keys.forEach(k => { if(!d.keys[k]) return; let cur = {}; try{ cur = JSON.parse(localStorage.getItem(k) || "{}"); }catch(e){} localStorage.setItem(k, JSON.stringify(Object.assign(cur, d.keys[k]))); });
